# -*- coding: utf-8 -*-
from taf.playwright.sbts.common.exceptions import SbtsFeatureNotMigrated
from taf.playwright.sbts.common.basic_page import PlaywrightBasicPage


class PendingDomain(object):
    """Explicit placeholder for Selenium SBTS domains pending Playwright migration."""

    def __init__(self, domain_name):
        self.domain_name = domain_name

    def __getattr__(self, keyword_name):
        def _missing(*args, **kwargs):
            raise SbtsFeatureNotMigrated(
                "SBTS domain {!r} keyword {!r} is not migrated to taf.playwright.sbts yet".format(
                    self.domain_name, keyword_name
                )
            )
        return _missing


class BtsBasicInfoDomain(object):
    """Small Playwright-backed subset of the Selenium bts_basic_info domain."""

    def __init__(self, bts_status_page):
        self._bts_status_page = bts_status_page

    def get_bts_status(self, technology=None, timeout=5):
        return self._bts_status_page.get_status(timeout=timeout, technology=technology)


class NavigableDomain(PendingDomain, PlaywrightBasicPage):
    """Reusable domain template for first-wave Playwright page migration."""

    def __init__(self, page, domain_name, route):
        PendingDomain.__init__(self, domain_name)
        PlaywrightBasicPage.__init__(self, page)
        self.route = route

    def navigate_to(self, timeout=60):
        for item in self.route:
            if not self.optional_click('text="{}"'.format(item), timeout=timeout):
                self.click('text={}'.format(item), timeout=timeout)
        return True


class ConfigurationDomain(NavigableDomain):
    def __init__(self, page):
        super(ConfigurationDomain, self).__init__(page, "configuration", ["Configuration"])


class DiagnosticDomain(NavigableDomain):
    def __init__(self, page):
        super(DiagnosticDomain, self).__init__(page, "diagnostic", ["Diagnostics"])


class SoftwareDomain(NavigableDomain):
    def __init__(self, page):
        super(SoftwareDomain, self).__init__(page, "software", ["Software"])


class AlarmsDomain(NavigableDomain):
    def __init__(self, page):
        super(AlarmsDomain, self).__init__(page, "alarms", ["Fault Management", "Alarms"])


class PerformanceDomain(NavigableDomain):
    def __init__(self, page):
        super(PerformanceDomain, self).__init__(page, "performance", ["Performance"])


class CommissioningDomain(NavigableDomain):
    def __init__(self, page):
        super(CommissioningDomain, self).__init__(
            page,
            "commissioning",
            ["Configuration", "Configuration Management", "Commissioning Wizard"],
        )

    def go_to_target_path_under_commissioning_tab(self, target_tab_path, timeout=60):
        self.navigate_to(timeout=timeout)
        if isinstance(target_tab_path, (list, tuple)):
            path_items = target_tab_path
        else:
            path_items = [item.strip() for item in str(target_tab_path).split(">") if item.strip()]
        for item in path_items:
            if not self.optional_click('text="{}"'.format(item), timeout=timeout):
                self.click('text={}'.format(item), timeout=timeout)
        return True
